import { createLayoutState, normalizeLayout } from "../state/layout";
import { collectLeafIds, createLeafNode } from "../state/paneTree";
import type { WorkspaceState } from "../state/workspaceStore";
import { loadBrowserSettings } from "./browserSettings";
import {
  worktreeIdentity,
  type BrowserTab,
  type LayoutState,
  type PersistedLayout,
  type PersistedTab,
  type PersistedTerminalSession,
  type PersistedWorkspace,
  type PersistedWorkspaceSession,
  type PersistedWorktree,
  type TabGroup,
  type TerminalSession,
  type TerminalTab,
  type WorkspaceTab,
  type Worktree,
} from "./types";

export const WORKSPACE_SESSION_VERSION = 2;

export function serializeWorkspaceState(
  workspaceId: string,
  repoRoot: string,
  state: WorkspaceState,
  existingSession?: PersistedWorkspaceSession | null,
): PersistedWorkspaceSession {
  const browserSettings = loadBrowserSettings();
  const restoreBrowserTabs = browserSettings.restoreTabsOnLaunch;

  const persistedWorktrees: PersistedWorktree[] = state.worktrees.map((wt) => ({
    path: wt.path,
    branch: wt.branch ?? "",
    head: wt.head,
    isMain: !wt.branch || wt.branch === "main" || wt.branch === "master",
    isLocked: Boolean(wt.locked),
  }));

  function serializeLayout(layoutState: LayoutState): PersistedLayout {
    const normalizedLayout = normalizeLayout(layoutState);
    const persistedTabs: PersistedTab[] = [];
    for (const tab of normalizedLayout.tabs) {
      if (tab.kind === "browser") {
        if (!restoreBrowserTabs) continue;
        persistedTabs.push({
          id: tab.id,
          kind: "browser",
          label: tab.label,
          pinned: Boolean(tab.pinned),
          browser: {
            browserId: tab.browserId,
            url: tab.url,
            title: tab.title ?? null,
            loading: tab.loading,
            canGoBack: tab.canGoBack,
            canGoForward: tab.canGoForward,
            profileId: tab.profileId,
            worktreePath: tab.worktreePath,
            worktreeLabel: tab.worktreeLabel,
          },
        });
        continue;
      }

      const tabLayout = normalizedLayout.layoutsByTabId[tab.id];
      persistedTabs.push({
        id: tab.id,
        kind: "terminal",
        label: tab.label,
        pinned: Boolean(tab.pinned),
        terminal: tabLayout
          ? {
              primarySessionId: tab.sessionId,
              paneTree: tabLayout.root,
              sessionIdsByLeafId: { ...tabLayout.sessionIdsByLeafId },
              activeLeafId: tabLayout.activeLeafId,
              expandedLeafId: tabLayout.expandedLeafId,
            }
          : {
              primarySessionId: tab.sessionId,
              paneTree: createLeafNode(`leaf-persisted:${tab.id}`),
              sessionIdsByLeafId: { [`leaf-persisted:${tab.id}`]: tab.sessionId },
              activeLeafId: `leaf-persisted:${tab.id}`,
              expandedLeafId: null,
            },
      });
    }

    const tabIds = new Set(persistedTabs.map((t) => t.id));
    const activeTabId =
      normalizedLayout.activeTabId && tabIds.has(normalizedLayout.activeTabId)
        ? normalizedLayout.activeTabId
        : (persistedTabs[0]?.id ?? null);
    const primaryTabId =
      normalizedLayout.primaryTabId && tabIds.has(normalizedLayout.primaryTabId)
        ? normalizedLayout.primaryTabId
        : (persistedTabs[0]?.id ?? null);

    return {
      splitMode: normalizedLayout.split ?? "none",
      primaryTabId,
      secondaryTabId: normalizedLayout.secondaryTabId ?? null,
      activeTabId,
      tabs: persistedTabs,
      tabGroups: Object.values(normalizedLayout.tabGroups ?? {}).map((group) => ({
        id: group.id,
        tabIds: group.tabIds.filter((id) => tabIds.has(id)),
        activeTabId: group.activeTabId && tabIds.has(group.activeTabId) ? group.activeTabId : null,
      })),
      tabGroupLayout: normalizedLayout.tabGroupLayout ?? null,
      focusedGroupId: normalizedLayout.focusedGroupId ?? null,
    };
  }

  const persistedLayout = serializeLayout(state.layout);
  const persistedWorktreeLayouts: Record<string, PersistedLayout> = {};
  for (const [wtPath, layout] of Object.entries(state.worktreeLayouts ?? {})) {
    if (layout) {
      persistedWorktreeLayouts[wtPath] = serializeLayout(layout);
    }
  }

  const allPersistedLayouts = [persistedLayout, ...Object.values(persistedWorktreeLayouts)];
  const referencedSessionIds = new Set<string>();
  for (const layout of allPersistedLayouts) {
    for (const tab of layout.tabs) {
      if (tab.kind === "browser") continue;
      const terminal = tab.terminal;
      if (terminal?.primarySessionId) referencedSessionIds.add(terminal.primarySessionId);
      for (const sessionId of Object.values(terminal?.sessionIdsByLeafId ?? {})) {
        if (sessionId) referencedSessionIds.add(sessionId);
      }
    }
  }

  const persistedTerminalSessions: Record<string, PersistedTerminalSession> = {};
  const createdAt = Date.now();
  for (const [id, sess] of Object.entries(state.sessions)) {
    if (!sess || !referencedSessionIds.has(id)) continue;
    persistedTerminalSessions[id] = {
      localSessionId: sess.id,
      backendSessionId: sess.backendSessionId,
      worktreePath: sess.worktreePath ?? sess.cwd,
      cwd: sess.cwd,
      createdAt,
    };
  }

  const workspace: PersistedWorkspace = {
    workspaceId,
    repoRoot,
    worktrees: persistedWorktrees,
    activeWorktreePath: state.activeWorktreePath,
    layout: persistedLayout,
    ...(Object.keys(persistedWorktreeLayouts).length > 0 ? { worktreeLayouts: persistedWorktreeLayouts } : {}),
    terminalSessions: persistedTerminalSessions,
  };

  const workspaces = {
    ...(existingSession?.workspaces ?? {}),
    [workspaceId]: workspace,
  };

  return {
    version: WORKSPACE_SESSION_VERSION,
    timestamp: Date.now(),
    activeWorkspaceId: workspaceId,
    workspaces,
  };
}

export function deserializeWorkspaceState(
  workspaceId: string,
  persistedSession: PersistedWorkspaceSession,
  liveBackendSessionIds?: Iterable<string> | null,
): WorkspaceState | null {
  const ws = persistedSession.workspaces?.[workspaceId];
  if (!ws) return null;
  const isV2 = (persistedSession.version ?? 1) >= 2;

  const browserSettings = loadBrowserSettings();
  const restoreBrowser = browserSettings.restoreTabsOnLaunch;
  const knownProfiles = new Set(browserSettings.profiles.map((p) => p.id));
  const fallbackProfileId = browserSettings.defaultProfileId;

  const liveSet = liveBackendSessionIds
    ? (liveBackendSessionIds instanceof Set ? liveBackendSessionIds : new Set(liveBackendSessionIds))
    : null;

  const worktrees: Worktree[] = (ws.worktrees || []).map((wt) => ({
    path: wt.path,
    branch: wt.branch ? (wt.branch.startsWith("refs/heads/") ? wt.branch : `refs/heads/${wt.branch}`) : null,
    head: wt.head,
    bare: false,
    detached: false,
    locked: wt.isLocked ? "locked" : null,
    prunable: null,
  }));

  const sessions: Record<string, TerminalSession> = {};
  for (const [mapKey, sess] of Object.entries(ws.terminalSessions || {})) {
    const localSessionId = sess.localSessionId || mapKey || sess.sessionId || "";
    if (!localSessionId) continue;
    const persistedBackendSessionId = isV2 ? (sess.backendSessionId ?? null) : (sess.backendSessionId ?? sess.sessionId ?? null);
    const backendSessionId = liveSet
      ? (persistedBackendSessionId && liveSet.has(persistedBackendSessionId) ? persistedBackendSessionId : null)
      : persistedBackendSessionId;
    const worktreePath = sess.worktreePath || sess.cwd;
    const matchingWorktree = worktrees.find((wt) => wt.path === worktreePath);
    sessions[localSessionId] = {
      id: localSessionId,
      cwd: sess.cwd || worktreePath,
      worktreePath,
      workspaceId,
      worktree: matchingWorktree ? worktreeIdentity(matchingWorktree) : null,
      backendSessionId,
      lifecycle: backendSessionId ? "working" : "exited",
    };
  }

  function deserializeLayout(persistedLayout: PersistedLayout | undefined): LayoutState {
    if (!persistedLayout) return createLayoutState();

    const tabs: WorkspaceTab[] = [];
    for (const persistedTab of persistedLayout.tabs || []) {
      if (persistedTab.kind === "browser" || persistedTab.browser) {
        if (!restoreBrowser) continue;
        const browser = persistedTab.browser;
        const rawProfileId = browser?.profileId;
        const profileId = rawProfileId && knownProfiles.has(rawProfileId) ? rawProfileId : fallbackProfileId;
        const tab: BrowserTab = {
          id: persistedTab.id,
          kind: "browser",
          label: persistedTab.label,
          browserId: browser?.browserId ?? persistedTab.sessionId ?? `restored-browser:${persistedTab.id}`,
          url: browser?.url ?? "about:blank",
          title: browser?.title ?? persistedTab.label,
          canGoBack: browser?.canGoBack ?? false,
          canGoForward: browser?.canGoForward ?? false,
          loading: browser?.loading ?? false,
          pinned: Boolean(persistedTab.pinned),
          profileId,
          worktreePath: browser?.worktreePath ?? persistedTab.worktreePath,
          worktreeLabel: browser?.worktreeLabel,
        };
        tabs.push(tab);
        continue;
      }

      const primarySessionId = persistedTab.terminal?.primarySessionId ?? persistedTab.sessionId ?? "";
      const tab: TerminalTab = {
        id: persistedTab.id,
        kind: "terminal",
        sessionId: primarySessionId,
        label: persistedTab.label,
        pinned: Boolean(persistedTab.pinned),
      };
      tabs.push(tab);
    }

    const layoutsByTabId: LayoutState["layoutsByTabId"] = {};
    for (const persistedTab of persistedLayout.tabs || []) {
      if (persistedTab.kind === "browser" || persistedTab.browser) {
        if (!restoreBrowser) continue;
        const leafId = `leaf-browser:${persistedTab.id}`;
        layoutsByTabId[persistedTab.id] = {
          root: createLeafNode(leafId),
          activeLeafId: leafId,
          expandedLeafId: null,
          sessionIdsByLeafId: { [leafId]: "" },
        };
        continue;
      }

      const terminal = persistedTab.terminal;
      const legacyTabLayout = persistedLayout.layoutsByTabId?.[persistedTab.id];
      const paneTree = terminal?.paneTree ?? persistedTab.paneTree ?? legacyTabLayout?.root;
      const primarySessionId = terminal?.primarySessionId ?? persistedTab.sessionId ?? "";
      const root = paneTree ?? createLeafNode(`leaf-restored:${persistedTab.id}`);
      const leafIds = collectLeafIds(root);
      const persistedMapping =
        terminal?.sessionIdsByLeafId ?? persistedTab.sessionIdsByLeafId ?? legacyTabLayout?.sessionIdsByLeafId;
      const sessionIdsByLeafId = persistedMapping && Object.keys(persistedMapping).length > 0
        ? Object.fromEntries(leafIds.map((leafId) => [leafId, persistedMapping[leafId] ?? primarySessionId]))
        : Object.fromEntries(leafIds.map((leafId) => [leafId, primarySessionId]));
      const requestedActiveLeafId =
        terminal?.activeLeafId ?? persistedTab.activeLeafId ?? legacyTabLayout?.activeLeafId ?? null;
      const requestedExpandedLeafId =
        terminal?.expandedLeafId ?? persistedTab.expandedLeafId ?? legacyTabLayout?.expandedLeafId ?? null;
      layoutsByTabId[persistedTab.id] = {
        root,
        activeLeafId: requestedActiveLeafId && leafIds.includes(requestedActiveLeafId) ? requestedActiveLeafId : leafIds[0] ?? null,
        expandedLeafId:
          requestedExpandedLeafId && leafIds.includes(requestedExpandedLeafId) ? requestedExpandedLeafId : null,
        sessionIdsByLeafId,
      };
    }

    const tabGroups: Record<string, TabGroup> | undefined = persistedLayout.tabGroups?.length
      ? Object.fromEntries(
          persistedLayout.tabGroups.map((group) => [
            group.id,
            { id: group.id, tabIds: [...group.tabIds], activeTabId: group.activeTabId },
          ]),
        )
      : undefined;

    return normalizeLayout({
      tabs,
      primaryTabId: persistedLayout.primaryTabId || (tabs[0]?.id ?? null),
      secondaryTabId: persistedLayout.secondaryTabId || null,
      activeTabId: persistedLayout.activeTabId || (tabs[0]?.id ?? null),
      split: (persistedLayout.splitMode as LayoutState["split"]) || "none",
      nestedSplit: null,
      layoutsByTabId,
      tabGroups,
      tabGroupLayout: persistedLayout.tabGroupLayout ?? null,
      focusedGroupId: persistedLayout.focusedGroupId ?? null,
    });
  }

  const activeLayout = deserializeLayout(ws.layout);
  const worktreeLayouts: Record<string, LayoutState> = {};
  if (ws.worktreeLayouts) {
    for (const [wtPath, persistedWtLayout] of Object.entries(ws.worktreeLayouts)) {
      if (persistedWtLayout) {
        worktreeLayouts[wtPath] = deserializeLayout(persistedWtLayout);
      }
    }
  }

  const allLayouts = [activeLayout, ...Object.values(worktreeLayouts)];
  const referencedSessionIds = new Set<string>();
  for (const layout of allLayouts) {
    for (const tab of layout.tabs) {
      if (tab.kind === "browser") continue;
      if (tab.sessionId) referencedSessionIds.add(tab.sessionId);
      const tabLayout = layout.layoutsByTabId[tab.id];
      for (const sessionId of Object.values(tabLayout?.sessionIdsByLeafId ?? {})) {
        if (sessionId) referencedSessionIds.add(sessionId);
      }
    }
  }

  const referencedSessions = Object.fromEntries(
    Object.entries(sessions).filter(([sessionId]) => referencedSessionIds.has(sessionId)),
  );

  return {
    worktrees,
    activeWorktreePath: ws.activeWorktreePath || (worktrees[0]?.path ?? null),
    sessions: referencedSessions,
    layout: activeLayout,
    worktreeLayouts,
    unreadTabIds: {},
    unreadWorktreePaths: {},
    activityBySessionId: {},
  };
}

import { describe, expect, it } from "vitest";

import { getGroupForTab, layoutReducer, normalizeLayout } from "../state/layout";
import type { WorkspaceState } from "../state/workspaceStore";
import { saveBrowserSettings } from "./browserSettings";
import { deserializeWorkspaceState, serializeWorkspaceState, WORKSPACE_SESSION_VERSION } from "./sessionPersistence";

function workspaceState(): WorkspaceState {
  return {
    worktrees: [
      {
        path: "/workspace/main",
        head: "123456",
        branch: "main",
        bare: false,
        detached: false,
        locked: null,
        prunable: null,
      },
    ],
    activeWorktreePath: "/workspace/main",
    sessions: {
      "sess-1": {
        id: "sess-1",
        cwd: "/workspace/main/packages/api",
        worktreePath: "/workspace/main",
        workspaceId: "default",
        worktree: null,
        backendSessionId: "backend-1",
        lifecycle: "working",
      },
      "sess-2": {
        id: "sess-2",
        cwd: "/workspace/main",
        worktreePath: "/workspace/main",
        workspaceId: "default",
        worktree: null,
        backendSessionId: "backend-2",
        lifecycle: "working",
      },
      "sess-3": {
        id: "sess-3",
        cwd: "/workspace/main/packages/web",
        worktreePath: "/workspace/main",
        workspaceId: "default",
        worktree: null,
        backendSessionId: "backend-3",
        lifecycle: "working",
      },
    },
    unreadTabIds: {},
    unreadWorktreePaths: {},
    activityBySessionId: {},
    layout: {
      tabs: [
        { id: "tab-1", label: "main", sessionId: "sess-1", pinned: true },
        { id: "tab-2", label: "feature", sessionId: "sess-2" },
      ],
      primaryTabId: "tab-1",
      secondaryTabId: null,
      split: "horizontal",
      nestedSplit: null,
      activeTabId: "tab-1",
      layoutsByTabId: {
        "tab-1": {
          root: {
            type: "split",
            direction: "horizontal",
            first: { type: "leaf", leafId: "leaf-1" },
            second: { type: "leaf", leafId: "leaf-2" },
            ratio: 0.5,
          },
          activeLeafId: "leaf-2",
          expandedLeafId: "leaf-2",
          sessionIdsByLeafId: {
            "leaf-1": "sess-1",
            "leaf-2": "sess-3",
          },
        },
        "tab-2": {
          root: { type: "leaf", leafId: "leaf-feature" },
          activeLeafId: "leaf-feature",
          expandedLeafId: null,
          sessionIdsByLeafId: { "leaf-feature": "sess-2" },
        },
      },
    },
  };
}

describe("sessionPersistence v2 serialization and migration", () => {
  it("serializes typed terminal tabs, pane ownership, pinned/expanded state, and separate local/backend identities", () => {
    const serialized = serializeWorkspaceState("default", "/workspace/main", workspaceState());

    expect(serialized.version).toBe(WORKSPACE_SESSION_VERSION);
    expect(serialized.version).toBe(2);
    const workspace = serialized.workspaces.default;
    expect(workspace.repoRoot).toBe("/workspace/main");
    expect(workspace.layout.activeTabId).toBe("tab-1");

    const savedTab = workspace.layout.tabs[0];
    expect(savedTab.kind).toBe("terminal");
    expect(savedTab.pinned).toBe(true);
    expect(savedTab.terminal?.paneTree.type).toBe("split");
    expect(savedTab.terminal?.activeLeafId).toBe("leaf-2");
    expect(savedTab.terminal?.expandedLeafId).toBe("leaf-2");
    expect(savedTab.terminal?.sessionIdsByLeafId).toEqual({ "leaf-1": "sess-1", "leaf-2": "sess-3" });

    expect(workspace.terminalSessions["sess-1"]).toMatchObject({
      localSessionId: "sess-1",
      backendSessionId: "backend-1",
      worktreePath: "/workspace/main",
      cwd: "/workspace/main/packages/api",
    });
  });

  it("does not serialize terminal sessions that no tab or pane references", () => {
    const state = workspaceState();
    state.sessions["sess-orphan"] = {
      id: "sess-orphan",
      cwd: "/workspace/main",
      worktreePath: "/workspace/main",
      workspaceId: "default",
      worktree: null,
      backendSessionId: "backend-orphan",
      lifecycle: "working",
    };

    const serialized = serializeWorkspaceState("default", "/workspace/main", state);

    expect(serialized.workspaces.default.terminalSessions).not.toHaveProperty("sess-orphan");
  });

  it("round-trips Orca-style split tab groups without changing either tab's pane ownership", () => {
    const state = workspaceState();
    state.layout = normalizeLayout(state.layout);
    const targetGroupId = getGroupForTab(state.layout, "tab-1")!.id;
    state.layout = layoutReducer(state.layout, {
      type: "MOVE_TAB_TO_SPLIT",
      sourceTabId: "tab-2",
      targetGroupId,
      direction: "horizontal",
      position: "second",
    });

    const beforeTab1Group = getGroupForTab(state.layout, "tab-1");
    const beforeTab2Group = getGroupForTab(state.layout, "tab-2");
    expect(beforeTab1Group?.id).not.toBe(beforeTab2Group?.id);

    const serialized = serializeWorkspaceState("default", "/workspace/main", state);
    expect(serialized.workspaces.default.layout.tabGroups).toHaveLength(2);
    expect(serialized.workspaces.default.layout.tabGroupLayout).toMatchObject({ type: "split", direction: "horizontal" });

    const restored = deserializeWorkspaceState("default", serialized);
    expect(restored).not.toBeNull();
    expect(getGroupForTab(restored!.layout, "tab-1")?.id).not.toBe(getGroupForTab(restored!.layout, "tab-2")?.id);
    expect(restored!.layout.tabGroupLayout).toEqual(state.layout.tabGroupLayout);
    expect(restored!.layout.focusedGroupId).toBe(state.layout.focusedGroupId);
    expect(restored!.layout.layoutsByTabId["tab-1"]).toEqual(state.layout.layoutsByTabId["tab-1"]);
    expect(restored!.layout.layoutsByTabId["tab-2"]).toEqual(state.layout.layoutsByTabId["tab-2"]);
  });

  it("matches live native PTYs by backendSessionId instead of the frontend-local session id", () => {
    const serialized = serializeWorkspaceState("default", "/workspace/main", workspaceState());
    const restored = deserializeWorkspaceState("default", serialized, new Set(["backend-1", "backend-3"]));

    expect(restored).not.toBeNull();
    expect(restored!.sessions["sess-1"].backendSessionId).toBe("backend-1");
    expect(restored!.sessions["sess-2"].backendSessionId).toBeNull();
    expect(restored!.sessions["sess-3"].backendSessionId).toBe("backend-3");
    expect(restored!.sessions["sess-1"].cwd).toBe("/workspace/main/packages/api");
    expect(restored!.sessions["sess-1"].worktreePath).toBe("/workspace/main");
  });

  it("drops persisted terminal sessions that no restored tab or pane references", () => {
    const serialized = serializeWorkspaceState("default", "/workspace/main", workspaceState());
    serialized.workspaces.default.terminalSessions["sess-orphan"] = {
      localSessionId: "sess-orphan",
      backendSessionId: null,
      worktreePath: "/workspace/main",
      cwd: "/workspace/main",
      createdAt: Date.now(),
    };

    const restored = deserializeWorkspaceState("default", serialized, new Set());

    expect(restored).not.toBeNull();
    expect(restored!.sessions).not.toHaveProperty("sess-orphan");
  });

  it("round-trips explicit browser metadata rather than guessing browser kind from a pane tree", () => {
    saveBrowserSettings({ restoreTabsOnLaunch: true });
    const state = workspaceState();
    state.layout.tabs.push({
      kind: "browser",
      id: "tab-browser",
      label: "Docs",
      browserId: "browser-42",
      url: "https://example.com/docs",
      title: "Example Docs",
      loading: false,
      canGoBack: true,
      canGoForward: false,
      pinned: true,
    });
    state.layout.layoutsByTabId["tab-browser"] = {
      root: { type: "leaf", leafId: "leaf-browser" },
      activeLeafId: "leaf-browser",
      expandedLeafId: null,
      sessionIdsByLeafId: { "leaf-browser": "" },
    };

    const serialized = serializeWorkspaceState("default", "/workspace/main", state);
    const savedBrowser = serialized.workspaces.default.layout.tabs.find((tab) => tab.id === "tab-browser");
    expect(savedBrowser).toMatchObject({
      kind: "browser",
      pinned: true,
      browser: {
        browserId: "browser-42",
        url: "https://example.com/docs",
        title: "Example Docs",
        canGoBack: true,
        canGoForward: false,
      },
    });

    const restored = deserializeWorkspaceState("default", serialized)!;
    expect(restored.layout.tabs.find((tab) => tab.id === "tab-browser")).toMatchObject({
      kind: "browser",
      browserId: "browser-42",
      url: "https://example.com/docs",
      pinned: true,
    });
  });

  it("migrates v1 worktree identity and legacy session identifiers", () => {
    const serialized = {
      version: 1,
      timestamp: Date.now(),
      activeWorkspaceId: "default",
      workspaces: {
        default: {
          workspaceId: "default",
          repoRoot: "/workspace/main",
          worktrees: [
            { path: "/workspace/main", branch: "refs/heads/main", head: "111", isMain: true, isLocked: false },
            { path: "/workspace/feature", branch: "refs/heads/orca/default/feature-branch", head: "222", isMain: false, isLocked: false },
          ],
          activeWorktreePath: "/workspace/feature",
          layout: {
            splitMode: "none" as const,
            primaryTabId: "tab-feature",
            secondaryTabId: null,
            activeTabId: "tab-feature",
            tabs: [
              { id: "tab-feature", sessionId: "sess-feature", label: "feature-branch", worktreePath: "/workspace/feature" },
              { id: "tab-main", sessionId: "sess-main", label: "main", worktreePath: "/workspace/main" },
            ],
          },
          terminalSessions: {
            "sess-feature": { sessionId: "sess-feature", cwd: "/workspace/feature", worktreePath: "/workspace/feature", createdAt: Date.now() },
            "sess-main": { sessionId: "sess-main", cwd: "/workspace/main", worktreePath: "/workspace/main", createdAt: Date.now() },
          },
        },
      },
    };

    const restored = deserializeWorkspaceState("default", serialized as any);
    expect(restored).not.toBeNull();
    expect(restored!.sessions["sess-feature"].worktree).toEqual({ wsId: "default", slug: "feature-branch" });
    expect(restored!.sessions["sess-main"].worktree).toBeNull();
    expect(restored!.sessions["sess-feature"].backendSessionId).toBe("sess-feature");
  });

  it("maps a v1 pane tree with no per-leaf mapping by leafId rather than tab id", () => {
    const serialized = {
      version: 1,
      timestamp: Date.now(),
      activeWorkspaceId: "default",
      workspaces: {
        default: {
          workspaceId: "default",
          repoRoot: "/workspace/main",
          worktrees: [{ path: "/workspace/main", branch: "refs/heads/main", head: "111", isMain: true, isLocked: false }],
          activeWorktreePath: "/workspace/main",
          layout: {
            splitMode: "none" as const,
            primaryTabId: "tab-1",
            secondaryTabId: null,
            activeTabId: "tab-1",
            tabs: [
              {
                id: "tab-1",
                sessionId: "sess-1",
                label: "terminal",
                worktreePath: "/workspace/main",
                paneTree: {
                  type: "split" as const,
                  direction: "horizontal" as const,
                  first: { type: "leaf" as const, leafId: "leaf-alpha" },
                  second: { type: "leaf" as const, leafId: "leaf-beta" },
                  ratio: 0.5,
                },
              },
            ],
          },
          terminalSessions: {
            "sess-1": { sessionId: "sess-1", cwd: "/workspace/main", worktreePath: "/workspace/main", createdAt: Date.now() },
          },
        },
      },
    };

    const restored = deserializeWorkspaceState("default", serialized as any)!;
    expect(restored.layout.layoutsByTabId["tab-1"].sessionIdsByLeafId).toEqual({
      "leaf-alpha": "sess-1",
      "leaf-beta": "sess-1",
    });
    expect(restored.layout.layoutsByTabId["tab-1"].sessionIdsByLeafId["tab-1"]).toBeUndefined();
  });

  it("round-trips multi-worktree workspace state with active and parked worktree layouts without session leakage", () => {
    saveBrowserSettings({ restoreTabsOnLaunch: true });

    const state: WorkspaceState = {
      worktrees: [
        {
          path: "/workspace/main",
          head: "111111",
          branch: "main",
          bare: false,
          detached: false,
          locked: null,
          prunable: null,
        },
        {
          path: "/workspace/feature",
          head: "222222",
          branch: "refs/heads/orca/default/feature-x",
          bare: false,
          detached: false,
          locked: null,
          prunable: null,
        },
      ],
      activeWorktreePath: "/workspace/main",
      sessions: {
        "sess-main": {
          id: "sess-main",
          cwd: "/workspace/main/services/api",
          worktreePath: "/workspace/main",
          workspaceId: "default",
          worktree: null,
          backendSessionId: "backend-main",
          lifecycle: "working",
        },
        "sess-feature": {
          id: "sess-feature",
          cwd: "/workspace/feature/frontend",
          worktreePath: "/workspace/feature",
          workspaceId: "default",
          worktree: { wsId: "default", slug: "feature-x" },
          backendSessionId: "backend-feature",
          lifecycle: "working",
        },
        "sess-orphan": {
          id: "sess-orphan",
          cwd: "/workspace/main",
          worktreePath: "/workspace/main",
          workspaceId: "default",
          worktree: null,
          backendSessionId: "backend-orphan",
          lifecycle: "working",
        },
      },
      unreadTabIds: {},
      unreadWorktreePaths: {},
      activityBySessionId: {},
      layout: {
        tabs: [
          { id: "tab-main-1", label: "main terminal", sessionId: "sess-main", pinned: true },
        ],
        primaryTabId: "tab-main-1",
        secondaryTabId: null,
        split: "none",
        nestedSplit: null,
        activeTabId: "tab-main-1",
        layoutsByTabId: {
          "tab-main-1": {
            root: { type: "leaf", leafId: "leaf-main-1" },
            activeLeafId: "leaf-main-1",
            expandedLeafId: null,
            sessionIdsByLeafId: { "leaf-main-1": "sess-main" },
          },
        },
      },
      worktreeLayouts: {
        "/workspace/feature": {
          tabs: [
            { id: "tab-feat-term", label: "feature terminal", sessionId: "sess-feature" },
            {
              kind: "browser",
              id: "tab-feat-browser",
              label: "Feature Preview",
              browserId: "browser-feat-1",
              url: "http://localhost:5173",
              title: "Feature App",
              loading: false,
              canGoBack: true,
              canGoForward: false,
              pinned: false,
            },
          ],
          primaryTabId: "tab-feat-term",
          secondaryTabId: null,
          split: "none",
          nestedSplit: null,
          activeTabId: "tab-feat-term",
          layoutsByTabId: {
            "tab-feat-term": {
              root: { type: "leaf", leafId: "leaf-feat-1" },
              activeLeafId: "leaf-feat-1",
              expandedLeafId: null,
              sessionIdsByLeafId: { "leaf-feat-1": "sess-feature" },
            },
            "tab-feat-browser": {
              root: { type: "leaf", leafId: "leaf-browser-feat" },
              activeLeafId: "leaf-browser-feat",
              expandedLeafId: null,
              sessionIdsByLeafId: { "leaf-browser-feat": "" },
            },
          },
        },
      },
    };

    const serialized = serializeWorkspaceState("default", "/workspace/main", state);

    expect(serialized.workspaces.default.worktreeLayouts).toBeDefined();
    expect(serialized.workspaces.default.worktreeLayouts?.["/workspace/feature"]).toBeDefined();
    const parkedSerialized = serialized.workspaces.default.worktreeLayouts!["/workspace/feature"];
    expect(parkedSerialized.tabs).toHaveLength(2);
    expect(parkedSerialized.tabs[0]).toMatchObject({
      id: "tab-feat-term",
      kind: "terminal",
      terminal: {
        primarySessionId: "sess-feature",
        sessionIdsByLeafId: { "leaf-feat-1": "sess-feature" },
      },
    });
    expect(parkedSerialized.tabs[1]).toMatchObject({
      id: "tab-feat-browser",
      kind: "browser",
      browser: {
        browserId: "browser-feat-1",
        url: "http://localhost:5173",
      },
    });

    // Both referenced sessions must be persisted; orphan session must be dropped (no leakage)
    expect(serialized.workspaces.default.terminalSessions["sess-main"]).toBeDefined();
    expect(serialized.workspaces.default.terminalSessions["sess-feature"]).toBeDefined();
    expect(serialized.workspaces.default.terminalSessions).not.toHaveProperty("sess-orphan");

    const restored = deserializeWorkspaceState(
      "default",
      serialized,
      new Set(["backend-main", "backend-feature"]),
    );
    expect(restored).not.toBeNull();
    if (!restored) return;

    expect(restored.activeWorktreePath).toBe("/workspace/main");
    expect(restored.layout.tabs).toHaveLength(1);
    expect(restored.layout.tabs[0].id).toBe("tab-main-1");
    expect(restored.layout.layoutsByTabId["tab-main-1"].sessionIdsByLeafId).toEqual({
      "leaf-main-1": "sess-main",
    });

    expect(restored.worktreeLayouts).toBeDefined();
    expect(restored.worktreeLayouts?.["/workspace/feature"]).toBeDefined();
    const parkedRestored = restored.worktreeLayouts!["/workspace/feature"];
    expect(parkedRestored.tabs).toHaveLength(2);
    expect(parkedRestored.tabs[0]).toMatchObject({
      id: "tab-feat-term",
      kind: "terminal",
      sessionId: "sess-feature",
    });
    expect(parkedRestored.tabs[1]).toMatchObject({
      id: "tab-feat-browser",
      kind: "browser",
      browserId: "browser-feat-1",
      url: "http://localhost:5173",
    });
    expect(parkedRestored.layoutsByTabId["tab-feat-term"].sessionIdsByLeafId).toEqual({
      "leaf-feat-1": "sess-feature",
    });

    // Verify session integrity and no orphan session leakage
    expect(Object.keys(restored.sessions).sort()).toEqual(["sess-feature", "sess-main"]);
    expect(restored.sessions["sess-main"]).toMatchObject({
      id: "sess-main",
      cwd: "/workspace/main/services/api",
      worktreePath: "/workspace/main",
      backendSessionId: "backend-main",
      lifecycle: "working",
      worktree: null,
    });
    expect(restored.sessions["sess-feature"]).toMatchObject({
      id: "sess-feature",
      cwd: "/workspace/feature/frontend",
      worktreePath: "/workspace/feature",
      backendSessionId: "backend-feature",
      lifecycle: "working",
      worktree: { wsId: "default", slug: "feature-x" },
    });
  });
});

